import{_ as a,a as t,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 134 He said that ...","description":"学习 间接引语的时态回移，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 134 He said that ...","description":"学习 间接引语的时态回移，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 间接引语的时态回移，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 133 Sensational news!","link":"/life/english/new-concept/book-1/unit-06/lesson-133"},"next":{"text":"第一册：英语初阶 · Lesson 135 The latest report","link":"/life/english/new-concept/book-1/unit-06/lesson-135"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 133 Sensational news!","link":"/life/english/new-concept/book-1/unit-06/lesson-133"},"next":{"text":"第一册：英语初阶 · Lesson 135 The latest report","link":"/life/english/new-concept/book-1/unit-06/lesson-135"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-134.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-134.md"}'),o={name:"life/english/new-concept/book-1/unit-06/lesson-134.md"};function i(l,e,r,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-134-he-said-that" tabindex="-1">第一册：英语初阶 · Lesson 134 He said that ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-134-he-said-that" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 134 He said that ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-133">配套课 Lesson 133</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>转述过去听到的消息 本课要掌握间接引语的时态回移，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>news</td><td>/njuːz/</td><td>n.</td><td>消息（不可数）</td><td>some news</td></tr><tr><td>sensational</td><td>/senˈseɪʃənl/</td><td>adj.</td><td>轰动的</td><td>a sensational report</td></tr><tr><td>reporter</td><td>/rɪˈpɔːtə/</td><td>n.</td><td>记者</td><td>a reporter</td></tr><tr><td>claim</td><td>/kleɪm/</td><td>v.</td><td>声称</td><td>claim that</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>said that — 过去转述</li><li>told us that — 告诉我们某事</li></ul><h2 id="语法讲解-间接引语的时态回移" tabindex="-1">语法讲解：间接引语的时态回移 <a class="header-anchor" href="#语法讲解-间接引语的时态回移" aria-label="Permalink to &quot;语法讲解：间接引语的时态回移&quot;">​</a></h2><p>过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Maya told us that she was studying abroad.</p></blockquote><p>玛雅告诉我们她正在国外学习。</p><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>told that 通常缺少听话者；用 told us that 或 said that。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Maya told us that she was studying abroad.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Maya told us that she was studying abroad. The reporter said that the bridge was closed.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“转述过去听到的消息”写两至三句，再读给同伴听。至少使用一次间接引语的时态回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。 Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 said/told：Maya ___ us that she was studying.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> told</p><p><strong>解析：</strong> 按本课规则判断：过去时 said/told 引出转述时，原话的一般现在时常回移为一般过去时，现在进行时常回移为过去进行时。代词要随说话者身份调整。如果事实仍然成立或属于普遍事实，英语也允许保留原时态；不是所有转述都必须回移。say 与 tell 的结构不同，told 后通常要有听话者。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“玛雅告诉我们她正在国外学习。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Maya told us that she was studying abroad.</p><p><strong>解析：</strong> Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The reporter said that the bridge was closed.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 记者说那座桥关闭了。</p><p><strong>解析：</strong> Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语的时态回移。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-135">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",i]]);export{p as __pageData,b as default};
